"""
L0 Property-Based Tests: State Machine Transitions.
Verifies invariants for a generic swarm node state machine.
States: BOOTSTRAPPING, ACTIVE, SUSPENDED, DEGRADED, TERMINATED
"""
from hypothesis import given, strategies as st
from enum import Enum, auto
import pytest

from swarm_components.node_state import NodeState, StateMachine, InvalidTransitionError

class State(Enum):
    BOOTSTRAPPING = auto()
    ACTIVE = auto()
    SUSPENDED = auto()
    DEGRADED = auto()
    TERMINATED = auto()

# Valid transition map
VALID_TRANSITIONS = {
    State.BOOTSTRAPPING: {State.ACTIVE, State.TERMINATED},
    State.ACTIVE: {State.SUSPENDED, State.DEGRADED, State.TERMINATED},
    State.SUSPENDED: {State.ACTIVE, State.TERMINATED},
    State.DEGRADED: {State.ACTIVE, State.TERMINATED},
    State.TERMINATED: set(),  # Terminal state
}

state_strategy = st.sampled_from(list(State))

@given(state_strategy)
def test_initial_state_is_bootstrapping(state):
    """State machine always starts in BOOTSTRAPPING."""
    sm = StateMachine(initial_state=State.BOOTSTRAPPING)
    assert sm.current_state == State.BOOTSTRAPPING

@given(state_strategy)
def test_valid_transitions_always_succeed(state):
    """All valid transitions from a state are accepted."""
    sm = StateMachine(initial_state=state)
    for target in VALID_TRANSITIONS[state]:
        sm.transition_to(target)
        assert sm.current_state == target

@given(state_strategy)
def test_invalid_transitions_raise_error(state):
    """All invalid transitions raise InvalidTransitionError."""
    sm = StateMachine(initial_state=state)
    valid_targets = VALID_TRANSITIONS[state]
    invalid_targets = set(State) - valid_targets - {state}
    for target in invalid_targets:
        with pytest.raises(InvalidTransitionError):
            sm.transition_to(target)
        # State must remain unchanged after failed transition
        assert sm.current_state == state

@given(state_strategy)
def test_terminated_is_absorbing(state):
    """Once TERMINATED, no further transitions are possible."""
    sm = StateMachine(initial_state=State.TERMINATED)
    for target in State:
        with pytest.raises(InvalidTransitionError):
            sm.transition_to(target)

@given(st.lists(state_strategy, min_size=1, max_size=10))
def test_transition_sequence_preserves_invariants(sequence):
    """Any sequence of transitions either succeeds or leaves state unchanged."""
    sm = StateMachine(initial_state=State.BOOTSTRAPPING)
    for target in sequence:
        try:
            sm.transition_to(target)
            # Invariant: current state is always a valid state
            assert sm.current_state in State
        except InvalidTransitionError:
            # Invariant: failed transition does not change state
            pass